/**

// ────────────────────────────────────────────────────────────────
// DO NOT EDIT THIS FILE.
//
// COPY of source-of-truth at
//   ~/.claude/standards/scripts/verify/_discover-components.mjs
//
// Local edits will be overwritten the next time
//   bash ~/.claude/standards/scripts/install-slice-gates.sh
// runs. Edit the ORIGINAL and re-install.
// ────────────────────────────────────────────────────────────────
 * _discover-components — the single source of truth for "where does a design-system
 * component live?", shared by every verify-component-*.mjs / verify-composite-*.mjs /
 * verify-page-*.mjs script.
 *
 * @version 1
 * @updated 2026-06-05
 *
 * NOTE FOR VENDORED COPIES: the verify-*.mjs scripts now IMPORT this helper. A project
 * that pins (vendors) a copy of standards/scripts/verify/ MUST include this file too,
 * or the verifiers will fail to load. Re-sync this file whenever its @version bumps.
 *
 * Historically each verifier hardcoded `src/components/ui/<Name>/`. That limited the
 * design-system discipline to ONE folder and left feature-located components ungated.
 * This helper broadens discovery without losing the guardrail:
 *
 *   A COMPONENT FOLDER is a directory D such that EITHER
 *     (a) D's immediate parent is `ui` whose parent is `components`  → atomic primitive
 *         e.g.  src/components/ui/Button/
 *     (b) D's immediate parent is `components` (and is NOT the `ui` dir itself) → either
 *         a generic UI sibling of ui/, or a feature-located component
 *         e.g.  src/components/Card/          (generic, sibling to ui/)
 *         e.g.  src/form/components/icon-button/   (feature-located)
 *   ...OR D matches one of the project's explicit `component_roots` globs (override).
 *
 * The `components/` ancestor requirement is the guardrail: it stops unrelated
 * `__specs__`-bearing folders (e.g. engine rules at features/rules/<rule>/__specs__)
 * from being mistaken for UI components.
 *
 * PER-PROJECT OVERRIDE: when `<projectRoot>/.standards/autonomy.yaml` declares
 *   component_roots:
 *     - "src/components/ui"
 *     - "src/components"
 *     - "src/form/components"
 * those roots (resolved relative to the project root) REPLACE the default rule, and a
 * component folder is any direct child of a listed root. This lets each project place
 * its components wherever it wants while keeping discovery mechanical.
 *
 * Returns an array of:
 *   { name, dir, specPath, hasSpec, isUi, root }
 *   - name:     the component folder name (e.g. "Button", "icon-button")
 *   - dir:      absolute path to the component folder
 *   - specPath: absolute path to <dir>/__specs__/spec.md if present, else spec.yaml
 *               (the dual-format resolved path; default label when neither exists)
 *   - hasSpec:  boolean — does a spec exist on disk in either format
 *   - isUi:     boolean — true when the folder is under a `components/ui/` parent
 *               (atomic primitive); false for generic-sibling / feature-located
 *   - root:     the discovery root this component was found under
 *
 * Verifiers decide what to do with hasSpec=false (require it, or skip it).
 */
import { readdirSync, existsSync, readFileSync } from "node:fs";
import { join, resolve, basename, dirname, sep as pathSep } from "node:path";
import { resolveSpecFile, specFileExists } from "../lib/load-spec.mjs";

const IGNORE_DIRS = new Set([
  "node_modules", ".next", ".turbo", "dist", "build", "coverage", ".git",
  "storybook-static", "__tests__", "__stories__", "__specs__", "shadcn",
]);

/**
 * Read an optional `component_roots:` list from the nearest `.standards/autonomy.yaml`
 * at or above `srcRoot`. Dependency-free line parse (no yaml package needed): collects
 * `- "<glob>"` items under a top-level `component_roots:` key. Returns [] when absent.
 */
function readComponentRootsOverride(srcRoot) {
  let dir = resolve(srcRoot);
  for (let i = 0; i < 8 && dir !== dirname(dir); i++) {
    const cand = join(dir, ".standards", "autonomy.yaml");
    if (existsSync(cand)) {
      const text = readFileSync(cand, "utf-8");
      const roots = [];
      let inBlock = false;
      for (const raw of text.split("\n")) {
        const line = raw.replace(/\t/g, "  ");
        if (/^component_roots:\s*$/.test(line.trim()) || /^component_roots:\s*\[/.test(line.trim())) {
          inBlock = true;
          // inline array form: component_roots: ["a", "b"]
          const inline = line.match(/\[([^\]]*)\]/);
          if (inline) {
            for (const m of inline[1].matchAll(/["']([^"']+)["']/g)) roots.push(m[1]);
            inBlock = false;
          }
          continue;
        }
        if (inBlock) {
          if (/^\s*-\s/.test(line)) {
            const m = line.match(/-\s*["']?([^"'\n]+?)["']?\s*$/);
            if (m) roots.push(m[1].trim());
          } else if (line.trim() !== "" && !/^\s/.test(line)) {
            inBlock = false; // dedented to a new top-level key
          }
        }
      }
      return { roots, projectRoot: dir };
    }
    dir = dirname(dir);
  }
  return { roots: [], projectRoot: null };
}

/** True when `dir`'s parent chain marks it as a component folder per the default rule. */
function isDefaultComponentDir(fullPath) {
  const name = basename(fullPath);
  const parent = basename(dirname(fullPath));
  const grandparent = basename(dirname(dirname(fullPath)));
  // The `components/ui/` directory itself is a CONTAINER, not a component — descend
  // into it to find the atomic primitives. (Without this guard the walk would treat
  // `ui` as a component and never reach Button/Input/etc. inside it.)
  if (name === "ui" && parent === "components") return false;
  if (parent === "ui" && grandparent === "components") return true;       // (a) atomic primitive
  if (parent === "components") return true;                                // (b) generic sibling / feature-located
  return false;
}

function makeRecord(dir, root) {
  const parent = basename(dirname(dir));
  const grandparent = basename(dirname(dirname(dir)));
  const isUi = parent === "ui" && grandparent === "components";
  const specsDir = join(dir, "__specs__");
  // Dual-format: spec.md (fenced machine block) wins, else legacy spec.yaml.
  const specPath = resolveSpecFile(specsDir);
  return {
    name: basename(dir),
    dir,
    specPath,
    hasSpec: specFileExists(specsDir),
    isUi,
    root,
  };
}

/**
 * Discover component folders under `srcRoot`.
 * @param {string} srcRoot - absolute or cwd-relative path to a package src root.
 * @returns {Array<{name,dir,specPath,hasSpec,isUi,root}>}
 */
export function discoverComponents(srcRoot) {
  const absRoot = resolve(srcRoot);
  if (!existsSync(absRoot)) return [];

  const { roots: overrideRoots, projectRoot } = readComponentRootsOverride(absRoot);
  const found = [];
  const seen = new Set();

  // Per-project override: each listed root's direct children are components.
  if (overrideRoots.length > 0 && projectRoot) {
    for (const r of overrideRoots) {
      const rootAbs = resolve(projectRoot, r);
      if (!existsSync(rootAbs)) continue;
      for (const entry of safeReadDir(rootAbs)) {
        if (!entry.isDirectory() || IGNORE_DIRS.has(entry.name) || entry.name === "ui") continue;
        const dir = join(rootAbs, entry.name);
        if (seen.has(dir)) continue;
        seen.add(dir);
        found.push(makeRecord(dir, r));
      }
      // also include components/ui children when the root IS components/
      const uiSub = join(rootAbs, "ui");
      if (existsSync(uiSub)) {
        for (const entry of safeReadDir(uiSub)) {
          if (!entry.isDirectory() || IGNORE_DIRS.has(entry.name)) continue;
          const dir = join(uiSub, entry.name);
          if (seen.has(dir)) continue;
          seen.add(dir);
          found.push(makeRecord(dir, r + "/ui"));
        }
      }
    }
    return found;
  }

  // Default rule: walk the tree; any dir whose parent chain marks it a component folder.
  (function walk(dir) {
    for (const entry of safeReadDir(dir)) {
      if (!entry.isDirectory() || IGNORE_DIRS.has(entry.name)) continue;
      const full = join(dir, entry.name);
      if (isDefaultComponentDir(full)) {
        if (!seen.has(full)) {
          seen.add(full);
          found.push(makeRecord(full, "(default: components/ rule)"));
        }
        continue; // a component folder is a leaf for discovery; don't descend into it
      }
      walk(full);
    }
  })(absRoot);

  return found;
}

function safeReadDir(dir) {
  try {
    return readdirSync(dir, { withFileTypes: true });
  } catch {
    return [];
  }
}

/** Components that have a spec.yaml (the ones every spec-requiring verifier cares about). */
export function discoverSpeccedComponents(srcRoot) {
  return discoverComponents(srcRoot).filter((c) => c.hasSpec);
}

/**
 * Build a predicate `(filePath) => boolean` that returns true when filePath lives
 * inside ANY discovered component folder. Use it in file-scanning verifiers
 * (tokens, state-vocab) to replace the old `components/ui` path test so they also
 * scan feature-located component source files.
 */
export function makeIsUnderComponent(srcRoot) {
  const dirs = discoverComponents(srcRoot).map((c) => resolve(c.dir));
  const sep = pathSep;
  return (filePath) => {
    const f = resolve(filePath);
    return dirs.some((d) => f === d || f.startsWith(d + sep));
  };
}

/**
 * Build a predicate `(filePath) => componentDir|null` that returns the discovered
 * component folder a file lives under (the most-specific match), or null. Use it in
 * file-scanning verifiers (tokens, state-vocab) to group per-file violations back to
 * the owning component so a per-feature exception.yaml can waive them.
 */
export function makeComponentDirOf(srcRoot) {
  const dirs = discoverComponents(srcRoot).map((c) => resolve(c.dir));
  const sep = pathSep;
  return (filePath) => {
    const f = resolve(filePath);
    let best = null;
    for (const d of dirs) {
      if ((f === d || f.startsWith(d + sep)) && (!best || d.length > best.length)) {
        best = d;
      }
    }
    return best;
  };
}
